"""QApplication entry point for the ``es-soundtrack-tool`` GUI."""

from __future__ import annotations

import logging
import sys

from PySide6.QtWidgets import QApplication

from es_ost.logging_setup import configure_logging

from .main_window import MainWindow

logger = logging.getLogger(__name__)

# Register the compiled Qt resource (generated by pyside6-rcc at build time).
# The import must be static: Nuitka only bundles modules it can see at compile
# time, and an importlib.import_module() call would silently drop the embedded
# .env from a frozen build. In a source checkout the module does not exist.
try:
    from . import rc_data  # noqa: F401
except ImportError:
    rc_data = None  # type: ignore[assignment]


def main() -> int:
    configure_logging()
    logger.info("es-soundtrack-tool starting")
    app = QApplication(sys.argv)
    app.setApplicationName("es-soundtrack-tool")
    window = MainWindow()
    window.show()
    logger.info("main window shown")
    exit_code = app.exec()
    logger.info("es-soundtrack-tool exiting (code=%d)", exit_code)
    return exit_code


if __name__ == "__main__":
    raise SystemExit(main())
